fn moteHash(a: u32, b: u32) -> f32 {
  let x = (a * 747796405u) ^ (b * 2891336453u + 12345u);
  let w = ((x >> ((x >> 28u) + 4u)) ^ x) * 277803737u;
  return f32((w >> 22u) ^ w) / 4294967295.0;
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let start = ctx.params.travel - 14.0;
  // Its own place along the tunnel, in whichever span of it the window is over now.
  let home = moteHash(ctx.index, 1u) * 60.0;
  let z = start + (home - start) - 60.0 * floor((home - start) / 60.0);
  let wall = pathFrame(z);
  let reach = ctx.params.bore * (1.0 + CHAMBER_SWELL * chamberAt(z)) * 0.9;
  let angle = moteHash(ctx.index, 2u) * 6.2831853;
  let radius = sqrt(moteHash(ctx.index, 3u)) * reach;
  let nerve = moteHash(ctx.index, 4u);
  // It hangs, and drifts a hand's width on a slow count of its own.
  let drift = vec2f(sin(ctx.absTime * (0.11 + nerve * 0.2) + nerve * 40.0), cos(ctx.absTime * (0.09 + nerve * 0.17) + nerve * 23.0)) * 0.12;
  var across = vec2f(cos(angle), sin(angle)) * radius + drift;
  // Nothing hangs under the deck.
  across.y = max(across.y, -ctx.params.bore * 0.7);
  q.position = wall.origin + wall.right * across.x + wall.up * across.y;

  // The lamp it is nearest, and the robot's eyes: inverse square, as the lights themselves fall off.
  let station = floor(z / LAMP);
  let lampAt = pathFrame((station + 0.5) * LAMP);
  // Under the plate, wherever the wall there holds it: a hall's crown is higher (CHAMBERS).
  let toLamp = lampAt.origin + lampAt.up * (ctx.params.bore * (1.0 + CHAMBER_SWELL * chamberAt((station + 0.5) * LAMP)) - 0.35) - q.position;
  let eyesAt = pathAt(ctx.params.travel + 0.9);
  let toEyes = eyesAt - q.position;
  let lit = lampTone(station) * ctx.params.lamp / (1.0 + dot(toLamp, toLamp)) + ctx.params.eyeColor * ctx.params.eyes / (0.3 + dot(toEyes, toEyes));
  let twinkle = 0.55 + 0.45 * sin(ctx.absTime * (0.8 + nerve * 2.5) + nerve * 60.0);
  q.tint = vec4f(lit * (0.006 * ctx.params.amount * twinkle), 0.5 + nerve);
  return q;
}

// T1561b — the pods on the fields' towers (src/projects/sentinel-bot/field.ts).
struct Params {
  travel: f32, // @default 0  Distance travelled along the line, metres.
  place: f32, // @default 0  0 the tunnel, 1 the fields.
};
// T1561b — the tunnel's centreline (generated by src/projects/sentinel-bot/path.ts).
const PATH_PERIOD: f32 = 960.0;

fn pathAt(z: f32) -> vec3f {
  return vec3f(14.0 * sin(0.0327249235 * z + 0.4) + 5.0 * sin(0.085084801 * z + 1.9), 6.0 * sin(0.0261799388 * z + 2.2) + 2.5 * sin(0.0719948316 * z + 0.7), z);
}

fn pathTangent(z: f32) -> vec3f {
  return normalize(vec3f(0.458148929 * cos(0.0327249235 * z + 0.4) + 0.425424005 * cos(0.085084801 * z + 1.9), 0.157079633 * cos(0.0261799388 * z + 2.2) + 0.179987079 * cos(0.0719948316 * z + 0.7), 1.0));
}

struct Frame {
  origin: vec3f,
  right: vec3f,
  up: vec3f,
  forward: vec3f,
};

// Chambers (src/projects/sentinel-bot/path.ts, CHAMBERS): 0 in the bore, 1 across a hall's middle.
const CHAMBER_SWELL: f32 = 0.9;
fn chamberAt(z: f32) -> f32 {
  let along = z - 96.0 * floor(z / 96.0);
  return 1.0 - smoothstep(6.0, 13.0, abs(along - 48.0));
}

fn pathFrame(z: f32) -> Frame {
  var frame: Frame;
  frame.origin = pathAt(z);
  frame.forward = pathTangent(z);
  frame.right = normalize(cross(vec3f(0.0, 1.0, 0.0), frame.forward));
  frame.up = cross(frame.forward, frame.right);
  return frame;
}

const FIELD_CELL: f32 = 24.00000;
const WINDOW_ACROSS: u32 = 11u;
const WINDOW_BEHIND: i32 = 3;
const FIELD_LAP: i32 = 40;
const FIELD_AVENUE: f32 = 12.00000;
const TOWER_SWELL: f32 = 1.60000;

// A cell's lot, 0 to 1 (field.ts, fieldLot: the same line).
fn fieldLot(across: i32, along: i32, salt: u32) -> f32 {
  let n = (u32(across + 4096) * 73856093u) ^ (u32(along + 4096) * 19349663u) ^ (salt * 83492791u);
  let m = (n ^ (n >> 15u)) * 2246822519u;
  return f32((m ^ (m >> 13u)) >> 8u) / 16777216.0;
}

struct Tower {
  cell: vec2i, // its cell of the ground plan: across, and along within the lap
  foot: vec3f, // where it crosses the height of the line: x, the line's y abreast of it, z
  radius: f32,
  lean: vec2f, // how far its top has gone over, metres across and along
  count: f32, // its own count, 0 to 1
  stands: f32, // 0 in the avenue: not there
};

// The tower of cell (`across`, `along`) of the ground plan.
fn towerIn(across: i32, along: i32) -> Tower {
  // Its lots are drawn from its place in the lap, so the lap's end does not change the field.
  let lap = along - FIELD_LAP * i32(floor(f32(along) / f32(FIELD_LAP)));
  var t: Tower;
  t.cell = vec2i(across, lap);
  let z = (f32(along) + 0.5 + (fieldLot(across, lap, 1u) - 0.5) * 0.6) * FIELD_CELL;
  let x = (f32(across) + 0.5 + (fieldLot(across, lap, 2u) - 0.5) * 0.6) * FIELD_CELL;
  let line = pathAt(z);
  t.foot = vec3f(x, line.y, z);
  t.radius = 2.4 + 2.6 * fieldLot(across, lap, 3u);
  t.lean = (vec2f(fieldLot(across, lap, 4u), fieldLot(across, lap, 5u)) - 0.5) * 9.0;
  t.count = fieldLot(across, lap, 6u);
  t.stands = step(FIELD_AVENUE + t.radius * TOWER_SWELL, abs(x - line.x));
  return t;
}

// The tower in slot `slot` of the window, with the robot `travel` metres along.
fn towerOf(slot: u32, travel: f32) -> Tower {
  let across = i32(floor(pathAt(travel).x / FIELD_CELL)) + i32(slot % WINDOW_ACROSS) - i32(WINDOW_ACROSS / 2u);
  let along = i32(floor(travel / FIELD_CELL)) + i32(slot / WINDOW_ACROSS) - WINDOW_BEHIND;
  return towerIn(across, along);
}

// Its middle, `h` metres above the line: it goes over a little, more the higher.
fn towerAxis(t: Tower, h: f32) -> vec3f {
  let over = (h / 100.0) * abs(h / 100.0);
  return t.foot + vec3f(t.lean.x * over, h, t.lean.y * over);
}

// How thick it is there: swellings a few tens of metres apart, and thinner toward the top.
fn towerGirth(t: Tower, h: f32) -> f32 {
  let swell = 1.0 + 0.24 * sin(h * 0.21 + t.count * 6.2831853) + 0.13 * sin(h * 0.63 + t.count * 17.0);
  return t.radius * swell * mix(1.2, 0.72, clamp((h + 70.00000) / 170.00000, 0.0, 1.0));
}

const POD_SHAPE = array<f32, 5>(0.05, 0.8, 1.0, 0.72, 0.05);

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let pod = ctx.index / 5u;
  let along = f32(ctx.index % 5u) / 4.00000;
  let t = towerOf(pod / 56u, ctx.params.travel);
  if (t.stands < 0.5 || ctx.params.place < 0.5) {
    q.position = vec3f(t.foot.x, -4000.0, t.foot.z);
    q.girth = 0.0;
    q.tint = vec4f(0.0);
    return q;
  }
  let which = i32(pod % 56u);
  // Its own lots, drawn from its tower's cell and its number on the tower.
  let own = t.cell.x * 64 + which;
  let rung = (f32(which) + fieldLot(own, t.cell.y, 11u)) / 56.00000;
  let h = mix(-26.00000, 34.00000, rung);
  // Round the tower by the golden angle, so no two rows line up.
  let turn = f32(which) * 2.3999632 + t.count * 6.2831853;
  let radial = vec3f(cos(turn), 0.0, sin(turn));
  let size = 0.75 + 0.6 * fieldLot(own, t.cell.y, 12u);
  // It hangs out from the trunk and a little up, its foot just inside the skin.
  let hang = normalize(radial + vec3f(0.0, 0.42, 0.0));
  let foot = towerAxis(t, h) + radial * (towerGirth(t, h) * 0.9);
  q.position = foot + hang * (1.5 * size * along);
  q.girth = POD_SHAPE[ctx.index % 5u] * 0.5 * size;
  // One in four is empty: a husk, all but dark.
  let alive = mix(0.06, 1.0, step(0.25, fieldLot(own, t.cell.y, 13u)));
  q.tint = vec4f(fieldLot(own, t.cell.y, 14u), rung, alive, along);
  return q;
}

