// Chambers (src/projects/sentinel-bot/path.ts, CHAMBERS): 0 in the bore, 1 across a hall's middle.
const CHAMBER_SWELL: f32 = 0.9;
fn chamberAt(z: f32) -> f32 {
  let along = z - 96.0 * floor(z / 96.0);
  return 1.0 - smoothstep(6.0, 13.0, abs(along - 48.0));
}

fn pathFrame(z: f32) -> Frame {
  var frame: Frame;
  frame.origin = pathAt(z);
  frame.forward = pathTangent(z);
  frame.right = normalize(cross(vec3f(0.0, 1.0, 0.0), frame.forward));
  frame.up = cross(frame.forward, frame.right);
  return frame;
}

const FIELD_CELL: f32 = 24.00000;
const WINDOW_ACROSS: u32 = 21u;
const WINDOW_BEHIND: i32 = 4;
const FIELD_LAP: i32 = 40;
const FIELD_AVENUE: f32 = 12.00000;
const TOWER_SWELL: f32 = 1.60000;

// A cell's lot, 0 to 1 (field.ts, fieldLot: the same line).
fn fieldLot(across: i32, along: i32, salt: u32) -> f32 {
  let n = (u32(across + 4096) * 73856093u) ^ (u32(along + 4096) * 19349663u) ^ (salt * 83492791u);
  let m = (n ^ (n >> 15u)) * 2246822519u;
  return f32((m ^ (m >> 13u)) >> 8u) / 16777216.0;
}

struct Tower {
  cell: vec2i, // its cell of the ground plan: across, and along within the lap
  foot: vec3f, // where it crosses the height of the line: x, the line's y abreast of it, z
  radius: f32,
  lean: vec2f, // how far its top has gone over, metres across and along
  count: f32, // its own count, 0 to 1
  stands: f32, // 0 in the avenue: not there
};

// The tower of cell (`across`, `along`) of the ground plan.
fn towerIn(across: i32, along: i32) -> Tower {
  // Its lots are drawn from its place in the lap, so the lap's end does not change the field.
  let lap = along - FIELD_LAP * i32(floor(f32(along) / f32(FIELD_LAP)));
  var t: Tower;
  t.cell = vec2i(across, lap);
  let z = (f32(along) + 0.5 + (fieldLot(across, lap, 1u) - 0.5) * 0.6) * FIELD_CELL;
  let x = (f32(across) + 0.5 + (fieldLot(across, lap, 2u) - 0.5) * 0.6) * FIELD_CELL;
  let line = pathAt(z);
  t.foot = vec3f(x, line.y, z);
  t.radius = 2.4 + 2.6 * fieldLot(across, lap, 3u);
  t.lean = (vec2f(fieldLot(across, lap, 4u), fieldLot(across, lap, 5u)) - 0.5) * 9.0;
  t.count = fieldLot(across, lap, 6u);
  t.stands = step(FIELD_AVENUE + t.radius * TOWER_SWELL, abs(x - line.x));
  return t;
}

// The tower in slot `slot` of the window, with the robot `travel` metres along.
fn towerOf(slot: u32, travel: f32) -> Tower {
  let across = i32(floor(pathAt(travel).x / FIELD_CELL)) + i32(slot % WINDOW_ACROSS) - i32(WINDOW_ACROSS / 2u);
  let along = i32(floor(travel / FIELD_CELL)) + i32(slot / WINDOW_ACROSS) - WINDOW_BEHIND;
  return towerIn(across, along);
}

// Its middle, `h` metres above the line: it goes over a little, more the higher.
fn towerAxis(t: Tower, h: f32) -> vec3f {
  let over = (h / 100.0) * abs(h / 100.0);
  return t.foot + vec3f(t.lean.x * over, h, t.lean.y * over);
}

// How thick it is there: swellings a few tens of metres apart, and thinner toward the top.
fn towerGirth(t: Tower, h: f32) -> f32 {
  let swell = 1.0 + 0.24 * sin(h * 0.21 + t.count * 6.2831853) + 0.13 * sin(h * 0.63 + t.count * 17.0);
  return t.radius * swell * mix(1.2, 0.72, clamp((h + 70.00000) / 170.00000, 0.0, 1.0));
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let t = towerOf(ctx.index / 18u, ctx.params.travel);
  let h = mix(-70.00000, 100.00000, f32(ctx.index % 18u) / 17.00000);
  if (t.stands < 0.5 || ctx.params.place < 0.5) {
    // Not there: the whole strip is one point with no radius, well under everything.
    q.position = vec3f(t.foot.x, -4000.0, t.foot.z);
    q.girth = 0.0;
    q.tint = vec4f(0.0);
    return q;
  }
  q.position = towerAxis(t, h);
  q.girth = towerGirth(t, h);
  q.tint = vec4f(t.count, h, t.radius, 1.0);
  return q;
}

parameters.source:
struct Params {
  glow: f32, // @default 90  Radiance of a bolt at full flash.
};
fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
  var o = surfaceDefaults(s);
  o.albedo = vec4f(0.0, 0.0, 0.0, 1.0);
  o.roughness = 1.0;
  o.metallic = 0.0;
  o.emissive = vec3f(0.62, 0.8, 1.0) * (p.glow * s.tint.r);
  return o;
}

// @use surface-detail
struct Params {
  wet: f32, // @default 0.4  How much water still runs: the tracks down the wall and the pools on the deck.
  grime: f32, // @default 0.85  Rust, soot and silt.
  lamp: f32, // @default 14  Radiance of the lamp plates in the crown.
  bore: f32, // @default 2.6  The tunnel's radius, metres: how far round the wall a share of a turn is.
  fixtures: f32, // @default 1  The tunnel's other lamps (bulkheads, a hall's tubes, beacons): 0 none.
};

// Chambers (src/projects/sentinel-bot/path.ts, CHAMBERS): 0 in the bore, 1 across a hall's middle.
const CHAMBER_SWELL: f32 = 0.9;
fn chamberAt(z: f32) -> f32 {
  let along = z - 96.0 * floor(z / 96.0);
  return 1.0 - smoothstep(6.0, 13.0, abs(along - 48.0));
}
const LAMP: f32 = 12.80000;
const LAMP_GAIN = array<f32, 15>(1.00, 0.20, 1.00, 1.00, 0.06, 0.40, 1.00, 1.00, 0.20, 0.06, 0.40, 1.00, 1.00, 0.20, 0.40);
// The light of the lamp at a station (tunnel.ts, LAMP_TONES and LAMP_GAINS): cold in the bore, sodium in a hall,
// every fifteenth an alarm; and of every run of fifteen, some are dead and some failing.
fn lampTone(station: f32) -> vec3f {
  let turn = station - 15.0 * floor(station / 15.0);
  if (abs(turn - 7.0) < 0.5) { return vec3f(1.0000, 0.1000, 0.0600); }
  let gain = LAMP_GAIN[u32(clamp(turn + 0.5, 0.0, 14.5))];
  return mix(vec3f(0.6200, 0.8400, 1.0000), vec3f(1.0000, 0.6200, 0.2800), step(0.5, chamberAt((station + 0.5) * LAMP))) * gain;
}

// THE TUNNEL'S OTHER LAMPS (the owner, 2026-10-06: "the tunnels could use a bit more detail work too, different
// lights at different positions in the tube"): bulkheads in the bore, tubes in a hall, a turning beacon either
// side of every alarm lamp (tunnel.ts, FIXTURES). They are drawn here: a lens that glows, and the pool it throws
// on the wall round it, painted. They light nothing else, the robot least of all. A lamp that lights is a Light,
// and this tunnel has several hundred of these: they become Lights fed by a pointset when that exists (§T1589b).
const FIXTURE: f32 = 3.20000;
const FIXTURE_COUNT: f32 = 300.0;
// A fixture's lot, 0 to 99, drawn from its number in the lap: tunnel.ts, fixtureLot, the same line (and why
// it scales by a multiply and a shift and never divides).
fn fixtureLot(index: f32, salt: u32) -> u32 {
  let place = u32(index - FIXTURE_COUNT * floor(index / FIXTURE_COUNT) + 0.5);
  return ((((place + salt * 977u) * 2654435761u) >> 16u) * 100u) >> 16u;
}
// 0 dead, 1 lit, 2 failing.
fn fixtureState(lot: u32, dead: u32, failing: u32) -> f32 {
  return select(select(2.0, 1.0, lot < failing), 0.0, lot < dead);
}
const WALL_TONE = vec3f(1.0, 0.5, 0.16);
const TUBE_TONE = vec3f(0.62, 1.0, 0.78);

// What a small lamp standing `proud` metres off a wall throws on it, as a share of what falls at its foot:
// the cosine law over the distance squared. `away2` is the distance along the wall from its foot, squared.
fn poolOf(away2: f32, proud: f32) -> f32 {
  let d2 = away2 + proud * proud;
  return proud * proud * proud / (d2 * sqrt(d2));
}

fn fixtureLuck(n: f32, salt: f32) -> f32 {
  return fract(sin(n * 91.3458 + salt * 17.13) * 47453.5453);
}

fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
  var o = surfaceDefaults(s);
  let what = s.tint.r;
  let own = s.tint.g;
  let around = s.tint.b;
  let along = s.tint.a;
  // 0 at the crown, 1 at the bottom of the bore.
  let low = abs(around - 0.5) * 2.0;
  let stain = detailFbm(s.world * 0.55, 4, s.footprint);
  let spall = detailFbm(s.world * 4.3, 4, s.footprint);
  let grit = detailFbm(s.world * 31.0, 3, s.footprint);
  // Water comes down the wall: tracks a hand wide that run the long way round it.
  let track = detailFbm(vec3f(along * 7.0, around * 2.2, 3.0), 3, s.footprint).value;
  // Not on the deck: there the angle round the bore barely changes across three metres of plate and jumps at the
  // seam under its middle, so a track was a stripe from wall to wall that stopped dead on the centre line
  // (the owner, 2026-10-06: "the floor has some stripey issues"). On the deck water stands: the pools, below.
  let run = smoothstep(0.6, 0.72, track) * (0.35 + 0.65 * low) * step(what, 2.5);
  let dirt = p.grime * smoothstep(0.3, 0.72, stain.value);
  let pit = smoothstep(0.52, 0.8, spall.value);

  // The liner: concrete segments, each cast on its own day.
  var albedo = mix(vec3f(0.03, 0.03, 0.032), vec3f(0.16, 0.135, 0.105), 0.25 + 0.75 * own) * (0.55 + 0.6 * stain.value);
  var rough = 0.9;
  var metal = 0.0;
  var relief = 0.14;
  if (what > 2.5) {
    // The deck: plate steel under silt.
    albedo = mix(vec3f(0.04, 0.038, 0.036), vec3f(0.09, 0.066, 0.04), dirt);
    rough = 0.78;
    metal = 0.5 * (1.0 - dirt);
    relief = 0.09;
  } else if (what > 1.5) {
    // Pipes and cable runs: ochre, oxide green or red lead, flaking to the iron.
    let paint = mix(mix(vec3f(0.13, 0.105, 0.03), vec3f(0.03, 0.07, 0.052), step(0.34, own)), vec3f(0.12, 0.03, 0.02), step(0.67, own));
    albedo = mix(paint, vec3f(0.06, 0.05, 0.046), pit);
    rough = 0.66;
    metal = 0.55 * pit;
    relief = 0.06;
  } else if (what > 0.5) {
    // Ribs: iron, mostly rust.
    albedo = mix(vec3f(0.05, 0.048, 0.05), vec3f(0.16, 0.066, 0.026), 0.35 + 0.65 * smoothstep(0.25, 0.7, spall.value) * p.grime);
    rough = 0.74;
    metal = 0.6 * (1.0 - pit);
    relief = 0.08;
  }
  // Rust and soot: brown where water has carried it, black where nothing has washed it.
  albedo = mix(albedo, vec3f(0.15, 0.062, 0.024), run * p.grime * 0.75);
  albedo = mix(albedo, vec3f(0.014, 0.014, 0.015), dirt * 0.55);
  // Silt at the foot of the wall.
  let silt = p.grime * smoothstep(0.62, 0.86, low + (stain.value - 0.5) * 0.25) * step(what, 2.5);
  albedo = mix(albedo, vec3f(0.07, 0.052, 0.034), silt * 0.8);
  // What still shines: the running tracks, and pools where the deck dips.
  let pool = step(2.5, what) * smoothstep(0.5, 0.62, stain.value);
  let film = clamp(p.wet * max(run * 0.9, pool), 0.0, 1.0);
  rough = mix(rough + 0.08 * (grit.value - 0.5), 0.12, film);
  albedo = albedo * (1.0 - 0.35 * film);

  o.albedo = vec4f(albedo, 1.0);
  o.roughness = clamp(rough, 0.06, 1.0);
  o.metallic = metal * (1.0 - film);
  // Pitted and spalled where dry; water lies flat.
  // (Fine grit in the normal made every lit metre of wall sparkle: it roughens, it does not glint.)
  o.normal = detailBump(s.normal, stain.gradient * 0.55 * 0.4 + spall.gradient * 4.3 * 0.42 + grit.gradient * 31.0 * 0.025, relief * (1.0 - 0.85 * film));

  // A lamp plate in the crown at every lamp station; each has its own steadiness.
  let station = floor(along / LAMP);
  let onPlate = (1.0 - smoothstep(0.3, 0.36, abs(along - (station + 0.5) * LAMP))) * (1.0 - smoothstep(0.012, 0.016, abs(around - 0.5)));
  let nerve = fract(sin(station * 12.9898) * 43758.5453);
  let flicker = 1.0 - step(0.82, nerve) * step(0.6, fract(sin(floor(s.absTime * 11.0) * 78.233 + station) * 43758.5453)) * 0.8;
  o.emissive = o.emissive + lampTone(station) * p.lamp * onPlate * flicker;

  // ── The other lamps: what each lens gives off, and what it throws on the wall round it ──
  let hall = chamberAt(along);
  let girth = 6.2831853 * p.bore * (1.0 + CHAMBER_SWELL * hall);
  let wallward = sign(around - 0.5);
  var lenses = vec3f(0.0);
  var thrown = vec3f(0.0);

  // A fixture's state (0 dead, 1 lit, 2 failing) as how much of its light it gives now: a failing one drops out nine times a second, by chance.
  let pair = floor(along / FIXTURE);
  let stutter = step(0.55, fixtureLuck(floor(s.absTime * 9.0), pair + 3.0 * wallward));

  // Bulkheads: in the plain bore, amber.
  let bulkheadSide = 2.0 * (pair - 2.0 * floor(pair * 0.5)) - 1.0;
  let bulkheadOff = vec2f(along - (pair + 0.75) * FIXTURE, (around - (0.5 + 0.2 * bulkheadSide)) * girth);
  let bulkhead = fixtureState(fixtureLot(pair, 1u), 45u, 88u);
  let bulkheadOn = min(bulkhead, 1.0) * (1.0 - 0.85 * step(1.5, bulkhead) * stutter) * (1.0 - smoothstep(0.25, 0.6, hall));
  let bulkheadLens = (1.0 - smoothstep(0.09, 0.11, abs(bulkheadOff.x))) * (1.0 - smoothstep(0.05, 0.065, abs(bulkheadOff.y)));
  lenses = lenses + WALL_TONE * (bulkheadOn * bulkheadLens * 0.4);
  thrown = thrown + WALL_TONE * (bulkheadOn * poolOf(dot(bulkheadOff, bulkheadOff), 0.4) * 0.22);

  // A hall's tubes: along both shoulders, 1.2 m of light between two ribs.
  let beside = (around - (0.5 + 0.21 * wallward)) * girth;
  let lengthways = abs(along - (pair + 0.25) * FIXTURE);
  let tube = fixtureState(fixtureLot(pair, select(2u, 3u, wallward > 0.0)), 42u, 86u);
  let tubeOn = min(tube, 1.0) * (1.0 - 0.9 * step(1.5, tube) * stutter) * smoothstep(0.5, 0.9, hall);
  let tubeLens = (1.0 - smoothstep(0.02, 0.035, abs(beside))) * (1.0 - smoothstep(0.58, 0.62, lengthways));
  // A line of light: what it throws falls with the distance from the line, and off its ends.
  let tubePool = 0.09 / (beside * beside + 0.09) * (1.0 - smoothstep(0.5, 1.8, lengthways));
  lenses = lenses + TUBE_TONE * (tubeOn * tubeLens * 0.5);
  thrown = thrown + TUBE_TONE * (tubeOn * tubePool * 0.1);

  // A beacon either side of every alarm lamp, low on the wall, turning: each wall sees it come round half a turn after the other.
  let turn = station - 15.0 * floor(station / 15.0);
  let alarmed = 1.0 - step(0.5, abs(turn - 7.0));
  let beaconOff = vec2f(along - (station + 0.5) * LAMP, (around - (0.5 + 0.3 * wallward)) * girth);
  let sweep = pow(0.5 + 0.5 * sin(s.absTime * 4.2 + 1.5707963 * wallward), 6.0);
  let beaconLens = 1.0 - smoothstep(0.07, 0.1, length(beaconOff));
  lenses = lenses + vec3f(1.0000, 0.1000, 0.0600) * (alarmed * beaconLens * (0.12 + sweep));
  thrown = thrown + vec3f(1.0000, 0.1000, 0.0600) * (alarmed * poolOf(dot(beaconOff, beaconOff), 0.7) * sweep * 0.5);

  // A lens under years of soot gives less; the wall shows what is thrown on it in its own colour.
  o.emissive = o.emissive + (lenses * (1.0 - 0.5 * dirt) + thrown * albedo) * (p.lamp * p.fixtures);
  return o;
}

// @use surface-detail
struct Params {
  lamp0: vec3f, // @default [0, 2.25, -19.2]  Where the lamp -2 stations on from the robot's own hangs.
  lamp1: vec3f, // @default [0, 2.25, -6.4]  Where the lamp -1 stations on from the robot's own hangs.
  lamp2: vec3f, // @default [0, 2.25, 6.4]  Where the lamp 0 stations on from the robot's own hangs.
  lamp3: vec3f, // @default [0, 2.25, 19.2]  Where the lamp 1 stations on from the robot's own hangs.
  lamp4: vec3f, // @default [0, 2.25, 32.0]  Where the lamp 2 stations on from the robot's own hangs.
  station: f32, // @default 37  The station the robot is under: which lamp is which tone.
  lamps: f32, // @default 6  Radiance of a lamp plate, as the steel reflects it.
  pool: f32, // @default 0.05  Radiance of the lit liner round a plate, as a share of the plate's.
  deck: f32, // @default 0.2  How much of all that the wet deck throws back up.
  air: f32, // @default 0  Radiance of the fields as the steel shows them (the lit mist below, the pods all round): none in the tunnel.
  podColor: vec3f, // @default [1, 0.04, 0.04]  The pods' light, which the steel shows too out there.
  gloss: f32, // @default 0.42  Roughness of the shell where nothing has worn or soiled it.
  steel: f32, // @default 0.3  How much of what it faces the shell throws back: 0.04 is enamel, 0.6 bare steel.
  wear: f32, // @default 0.8  How old it is: rubbed edges, rust, dust. 0 is as the kit left the works.
  hueFrom: f32, // @default 0  The lights' colour range starts at this hue, 0 to 1 round the wheel (0 red).
  hueTo: f32, // @default 0.03  …and ends at this one.
  spread: f32, // @default 0.6  How much of the range the lights are spread over: 0 all one colour, 1 the lenses (and the length of a tentacle) cover it all.
  shift: f32, // @default 0  Moves every light along the range, 0 to 1. Drive it from a level.
  eyeGlow: f32, // @default 9  Radiance of the eye lenses.
  eyeHits: f32, // @default 0  How much the lenses answer the drums instead of burning steadily: a third of them each to kick, snare and hat.
  kick: f32, // @default 0  The kick, 0 to 1 as it decays.
  snare: f32, // @default 0  The snare.
  hat: f32, // @default 0  The hat.
  eyeSweep: f32, // @default 0  How much a band of light crossing the face takes over from the steady glow.
  sweepPhase: f32, // @default 0  Where that band is: it crosses once for each whole number. Drive it from the beat.
  coreGlow: f32, // @default 0.07  Radiance of a tentacle's light segments at rest: low, so the segmenting shows and no more.
  pulseGlow: f32, // @default 1.6  Radiance of a segment fully charged.
};

// What each drawn piece brings of its own: the rig's point attributes of the same names (rig.ts).
struct Instance {
  charge: f32, // @default 0  How lit this piece's light segment is by what runs along the tentacle: 0 at rest, 1 fully.
  seed: f32, // @default 0  Which piece it is, 0 to 1: its wear is its own.
  along: f32, // @default 0  How far along its tentacle it is, 0 at the body to 1 at the claw: its place in the colour range.
  matte: f32, // @default 0  1 on a tentacle's rings: the dark segments between its lights.
};

fn hueColour(hue: f32) -> vec3f {
  let wheel = clamp(abs(fract(vec3f(hue) + vec3f(0.000000, 0.666667, 0.333333)) * 6.0 - 3.0) - 1.0, vec3f(0.0), vec3f(1.0));
  return wheel * 0.96 + 0.04;
}

// The colour of the light at a place (0 to 1) in the range.
fn lightColour(place: f32, p: Params) -> vec3f {
  return hueColour(mix(p.hueFrom, p.hueTo, clamp(place * p.spread + p.shift, 0.0, 1.0)));
}

// Chambers (src/projects/sentinel-bot/path.ts, CHAMBERS): 0 in the bore, 1 across a hall's middle.
const CHAMBER_SWELL: f32 = 0.9;
fn chamberAt(z: f32) -> f32 {
  let along = z - 96.0 * floor(z / 96.0);
  return 1.0 - smoothstep(6.0, 13.0, abs(along - 48.0));
}
const LAMP: f32 = 12.80000;
const LAMP_GAIN = array<f32, 15>(1.00, 0.20, 1.00, 1.00, 0.06, 0.40, 1.00, 1.00, 0.20, 0.06, 0.40, 1.00, 1.00, 0.20, 0.40);
// The light of the lamp at a station (tunnel.ts, LAMP_TONES and LAMP_GAINS): cold in the bore, sodium in a hall,
// every fifteenth an alarm; and of every run of fifteen, some are dead and some failing.
fn lampTone(station: f32) -> vec3f {
  let turn = station - 15.0 * floor(station / 15.0);
  if (abs(turn - 7.0) < 0.5) { return vec3f(1.0000, 0.1000, 0.0600); }
  let gain = LAMP_GAIN[u32(clamp(turn + 0.5, 0.0, 14.5))];
  return mix(vec3f(0.6200, 0.8400, 1.0000), vec3f(1.0000, 0.6200, 0.2800), step(0.5, chamberAt((station + 0.5) * LAMP))) * gain;
}

// What a ray going up (d.y > 0) from `here` sees of the lamp of `station` hanging at `lampAt`, in the level
// plane it hangs in. `pool` is the lit liner round the plate as a share of the plate's radiance; `soft`
// widens the plate's edge, metres (a rough mirror).
fn lampSeen(d: vec3f, here: vec3f, lampAt: vec3f, station: f32, pool: f32, soft: f32) -> vec3f {
  let lamp = lampAt - here;
  // The tunnel climbs and falls: a lamp below this height is round a bend of it.
  if (lamp.y < 0.3) { return vec3f(0.0); }
  let hit = d * (lamp.y / d.y);
  let across = hit.x - lamp.x;
  let along = hit.z - lamp.z;
  let plate = (1.0 - smoothstep(0.2, 0.26 + soft, abs(across))) * (1.0 - smoothstep(0.3, 0.36 + soft, abs(along)));
  let lit = exp(-(across * across + along * along) / 3.0) * pool;
  // Air between: a far lamp is a dim one.
  return lampTone(station) * (plate + lit) * exp(-length(hit) * 0.035);
}

fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
  var o = surfaceDefaults(s);
  let role = s.attr.z;
  var albedo = vec3f(p.steel * 0.92, p.steel * 0.96, p.steel * 1.05);
  var rough = p.gloss;
  var metal = 1.0;
  // Whether it ages, and whether it is a mirror to the lamps.
  var ages = 1.0;
  var mirrors = 1.0;
  if (role > 0.9) {
    // A lens: black glass over a lamp, brightest where it faces the viewer.
    let facing = max(dot(normalize(s.eye - s.world), s.normal), 0.0);
    // Each lens has a nerve of its own: the eyes are a hand's breadth apart in the robot's frame, so a coarse cell of it names one.
    let lens = floor(s.local * 7.0);
    let nerve = fract(sin(dot(lens, vec3f(12.9898, 78.233, 37.719))) * 43758.5453);
    let life = 0.8 + 0.2 * sin(s.absTime * (1.5 + nerve * 4.0) + nerve * 40.0);
    albedo = vec3f(0.006, 0.006, 0.006);
    rough = 0.08;
    metal = 0.0;
    // The drums: a third of the lenses each to kick, snare and hat. With Eye Hits up a lens sits low and flashes on its own drum.
    let drum = select(select(p.hat, p.snare, nerve < 0.667), p.kick, nerve < 0.333);
    let struck = mix(1.0, 0.25 + 2.6 * drum, clamp(p.eyeHits, 0.0, 1.0));
    // A band of light crossing the face from one side to the other, once for each whole number of the phase.
    let band = pow(0.5 + 0.5 * cos(6.2831853 * (s.local.x * 0.9 - p.sweepPhase)), 3.0);
    let swept = mix(1.0, 0.2 + 2.4 * band, clamp(p.eyeSweep, 0.0, 1.0));
    o.emissive = lightColour(nerve, p) * p.eyeGlow * (0.35 + 0.65 * facing * facing) * life * struck * swept;
    ages = 0.0;
    mirrors = 0.0;
  } else if (role > 0.7) {
    // The spine between the rings is the tentacle's light: a segment of it shows between every two
    // rings, so a tentacle is lit, dark, lit, dark all the way down (the owner, 2026-10-05: that
    // segmenting is the look). Lit from inside by what runs along the tentacle, over a low glow at
    // rest. Not a mirror: as one, every segment found a lamp whatever the tentacle was doing.
    albedo = vec3f(0.022, 0.02, 0.02);
    rough = 0.72;
    metal = 0.2;
    o.emissive = lightColour(s.instance.along, p) * (p.coreGlow + p.pulseGlow * s.instance.charge);
    ages = 0.3;
    mirrors = 0.0;
  } else if (role > 0.5) {
    // Red lead paint.
    albedo = vec3f(0.11, 0.012, 0.009);
    rough = 0.5;
    metal = 0.25;
  } else if (role > 0.3) {
    // Brass, long tarnished.
    albedo = vec3f(0.3, 0.2, 0.08);
    rough = 0.45;
  } else if (role > 0.1) {
    // Bright steel that has not been bright for years.
    albedo = vec3f(0.34, 0.345, 0.36);
    rough = 0.36;
  }

  // A tentacle's rings are the DARK segments between its lights, and must stay dark from every
  // angle (the owner: "the not lit up segments were taking on too much light color so they did
  // not appear as a segment"). As polished steel they mirrored the light beside them; they are
  // matt black instead, and show no lamp.
  if (role <= 0.1 && s.instance.matte > 0.5) {
    albedo = vec3f(0.012, 0.012, 0.013);
    rough = 0.88;
    metal = 0.0;
    ages = 0.25;
    mirrors = 0.0;
  }

  // ── Age ──
  let wear = p.wear * ages;
  var pitted = s.normal;
  if (wear > 0.0) {
    let skin = s.local + vec3f(17.0, 31.0, 7.0) * s.instance.seed;
    let blotch = detailFbm(skin * 2.6, 4, s.footprint).value;
    let wet = detailFbm(skin * 1.4 + vec3f(41.0, 13.0, 29.0), 3, s.footprint).value;
    let grain = detailFbm(skin * 48.0, 3, s.footprint);
    // Scores and scratches: long thin marks the way things have dragged along it, each a hair wide.
    let score = detailFbm(vec3f(skin.x * 55.0, skin.y * 55.0, skin.z * 2.5) + vec3f(9.0), 3, s.footprint).value;
    let scratched = wear * smoothstep(0.7, 0.76, score);
    // Edges and raised detail, rubbed through to the metal.
    let rubbed = clamp(wear * detailEdgeWear(s.curvature, 18.0, grain.value) + scratched * 0.85, 0.0, 1.0);
    albedo = mix(albedo, vec3f(0.55, 0.53, 0.5), rubbed * 0.8);
    rough = mix(rough, 0.3, rubbed * 0.7);
    metal = mix(metal, 1.0, rubbed);
    // Rust where it has stood wet, pitted.
    let rust = wear * smoothstep(0.46, 0.7, wet) * (0.4 + 0.6 * grain.value) * (1.0 - rubbed);
    albedo = mix(albedo, vec3f(0.17, 0.062, 0.022), rust);
    rough = mix(rough, 0.9, rust);
    metal = mix(metal, 0.0, rust);
    // Soot and oil baked on, in patches: darker and duller, still metal underneath.
    let soot = wear * smoothstep(0.38, 0.62, blotch) * (1.0 - rubbed);
    albedo = albedo * (1.0 - 0.6 * soot);
    rough = mix(rough, 0.78, soot * 0.7);
    // Dust lying on what faces up.
    let dust = wear * smoothstep(0.5, 0.75, 1.0 - blotch) * max(s.normal.y, 0.0) * (1.0 - rubbed);
    albedo = mix(albedo, vec3f(0.05, 0.045, 0.038), dust * 0.8);
    rough = mix(rough, 0.96, dust * 0.8);
    metal = mix(metal, 0.0, dust * 0.8);
    // And no patch of it quite as smooth as the next; pitted all over.
    rough = rough + wear * (grain.value - 0.5) * 0.3;
    pitted = detailBump(s.normal, grain.gradient * 48.0, 0.0035 * wear);
  }
  o.normal = pitted;
  o.albedo = vec4f(albedo, 1.0);
  o.roughness = clamp(rough, 0.05, 1.0);
  o.metallic = metal;

  // A mirror shows what is along its mirror direction: the lamps overhead, and their smear in the wet deck
  // below (tunnel.ts). Metal only, and hardly at all once it is rough.
  let view = normalize(s.world - s.eye);
  let mirror = reflect(view, s.normal);
  let soft = o.roughness * 0.6;
  // Looking down, it is the deck's own mirror image of the same lamps, dimmer.
  let up = vec3f(mirror.x, max(abs(mirror.y), 0.02), mirror.z);
  var seen = vec3f(0.0);
  seen = seen + lampSeen(up, s.world, p.lamp0, p.station + -2.0, p.pool, soft);
  seen = seen + lampSeen(up, s.world, p.lamp1, p.station + -1.0, p.pool, soft);
  seen = seen + lampSeen(up, s.world, p.lamp2, p.station + 0.0, p.pool, soft);
  seen = seen + lampSeen(up, s.world, p.lamp3, p.station + 1.0, p.pool, soft);
  seen = seen + lampSeen(up, s.world, p.lamp4, p.station + 2.0, p.pool, soft);
  seen = seen * select(p.deck, 1.0, mirror.y > 0.0);
  // Schlick: at a grazing angle any metal is a full mirror.
  let graze = pow(1.0 - max(dot(-view, s.normal), 0.0), 5.0);
  let polish = (1.0 - o.roughness) * (1.0 - o.roughness);
  o.emissive = o.emissive + seen * p.lamps * mix(o.albedo.rgb, vec3f(1.0), graze) * o.metallic * polish * mirrors;
  // Out in the fields there is no lamp to show and the steel is not black for that. What is round it out there
  // (field.ts, air.ts): mist below, lit cold, so what faces down shows it bright and what faces up shows the dark
  // overhead; and towers all round at its own height, red with pods, which polished steel shows as red glints.
  // So a robot has an underside, a top and edges, from any side, and is not a hole in the picture when the lens
  // is behind it and its own lights face away. (Rough steel shows the mist too, only without an image.)
  let below = smoothstep(0.35, -0.55, mirror.y);
  let towers = (1.0 - smoothstep(0.25, 0.7, abs(mirror.y))) * smoothstep(0.5, 0.68, detailFbm(mirror * 7.0, 2, 0.0).value);
  let fields = vec3f(0.27, 0.61, 1.0) * (0.1 + 1.5 * below) * (0.3 + 0.7 * polish) + p.podColor * (2.2 * towers * polish);
  o.emissive = o.emissive + fields * p.air * mix(o.albedo.rgb, vec3f(1.0), graze) * o.metallic * mirrors;
  return o;
}

struct Params {
  glow: f32, // @default 2.4  Radiance of a pod.
  hueFrom: f32, // @default 0  The lights' colour range starts at this hue, 0 to 1 round the wheel (0 red).
  hueTo: f32, // @default 0.03  …and ends at this one.
  low: f32, // @default 0  The low end of the track, 0 to 1.
  kick: f32, // @default 0  The kick, 0 to 1 as it decays.
  hat: f32, // @default 0  The hats, 0 to 1 as they decay.
  beat: f32, // @default 0  The beat's count: a whole number.
  react: f32, // @default 1  How much the pods answer the track.
  robotAt: vec3f, // @default [0, 0, 0]  Where the robot is: a kick goes out through the field from there.
};
fn hueColour(hue: f32) -> vec3f {
  let wheel = clamp(abs(fract(vec3f(hue) + vec3f(0.000000, 0.666667, 0.333333)) * 6.0 - 3.0) - 1.0, vec3f(0.0), vec3f(1.0));
  return wheel * 0.96 + 0.04;
}

fn fieldAnswer(p: Params, lot: f32, world: vec3f) -> f32 {
  let meter = smoothstep(lot - 0.1, lot + 0.1, (p.low - 0.3) * 1.3);
  let gone = length(world - p.robotAt);
  let ring = exp(-pow((gone - (1.0 - p.kick) * 150.00000) / 9.00000, 2.0)) * smoothstep(0.03, 0.2, p.kick);
  let spark = step(0.9375, fract(lot * 61.0 + p.beat * 0.6180340)) * p.hat * p.hat * p.hat;
  return 1.0 - 0.4 * min(p.react, 1.0) + p.react * (1.0 * meter + 2.2 * ring + 3.2 * spark);
}

fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
  var o = surfaceDefaults(s);
  let place = s.tint.r;
  let alive = s.tint.b;
  let along = s.tint.a;
  let facing = max(dot(normalize(s.eye - s.world), s.normal), 0.0);
  // What is inside lies toward the foot: the far end is membrane.
  let core = facing * facing * (0.25 + 0.75 * (1.0 - smoothstep(0.35, 0.95, along)));
  // Each breathes on a slow count of its own.
  let breath = 0.78 + 0.22 * sin(s.absTime * (0.5 + place * 0.9) + place * 40.0);
  o.albedo = vec4f(0.02, 0.012, 0.012, 1.0);
  o.roughness = 0.22;
  o.metallic = 0.0;
  o.emissive = hueColour(mix(p.hueFrom, p.hueTo, place)) * (p.glow * alive * (0.06 + core) * breath * fieldAnswer(p, place, s.world));
  return o;
}

// @use surface-detail
struct Params {
  glow: f32, // @default 2.4  Radiance of a pod.
  hueFrom: f32, // @default 0  The lights' colour range starts at this hue, 0 to 1 round the wheel (0 red).
  hueTo: f32, // @default 0.03  …and ends at this one.
