  let outward = kind < 0.80000;
  let b = towerIn(across + select(0, i32(side), outward), along + select(1, 0, outward));
  s.start = towerAxis(a, h);
  s.end = towerAxis(b, h + mix(-7.0, 7.0, strikeLot(strike, 5)));
  s.live = a.stands * b.stands;
  return s;
}
