// every fifteenth an alarm; and of every run of fifteen, some are dead and some failing.
fn lampTone(station: f32) -> vec3f {
  let turn = station - 15.0 * floor(station / 15.0);
  if (abs(turn - 7.0) < 0.5) { return vec3f(1.0000, 0.1000, 0.0600); }
  let gain = LAMP_GAIN[u32(clamp(turn + 0.5, 0.0, 14.5))];
  return mix(vec3f(0.6200, 0.8400, 1.0000), vec3f(1.0000, 0.6200, 0.2800), step(0.5, chamberAt((station + 0.5) * LAMP))) * gain;
}

// A lamp's light hangs this far under its plate (document.ts, lampAt); its lit air starts at the plate.
const LAMP_HANGS: f32 = 0.35;
const BEAM_GAIN: f32 = 1.00;
// How much of a point light at `light` the air along a ray throws back, per unit of the light and of the air's
// own share: the integral of 1/d² from the lens out to `reach` metres, dimmed by the air it then crosses.
fn airlight(origin: vec3f, ray: vec3f, reach: f32, light: vec3f) -> f32 {
  let q = origin - light;
  let b = dot(ray, q);
  // No nearer than a lamp is wide: a ray through the lamp itself is a bright core, not infinity.
  let c = sqrt(max(dot(q, q) - b * b, 0.03));
  let nearest = clamp(-b, 0.0, reach);
  return (atan((reach + b) / c) - atan(b / c)) / c * exp(-nearest * params.density);
}

// The same for a LAMP, which is not a point: it is a plate in the crown that shines down, most straight down
// and nothing above its own height (the cube of the cosine off straight down). So its lit air is a cone
// hanging from the plate, not a ball round a point under it. That integral is closed too, and has no
// arctangent in it: with s the distance along the ray from its nearest point to the plate, c that nearest
// distance, and the depth under the plate there under + sink * s, it is the integral of
// (under + sink * s)³ / (s² + c²)^(5/2), taken over the part of the ray that is below the plate.
// A hall's lamp is the bigger lamp, by how much higher it hangs (document.ts, lampAt).
fn hallLamp(z: f32) -> f32 {
  return 1.0 + CHAMBER_SWELL * chamberAt(z);
}

fn beamUpTo(s: f32, c2: f32, under: f32, sink: f32) -> f32 {
  let r2 = s * s + c2;
  let r3 = r2 * sqrt(r2);
  let j0 = s / (3.0 * c2 * r3) + 2.0 * s / (3.0 * c2 * c2 * sqrt(r2));
  let j1 = -1.0 / (3.0 * r3);
  let j2 = s * s * s / (3.0 * c2 * r3);
  let j3 = -(3.0 * s * s + 2.0 * c2) / (3.0 * r3);
  return under * under * under * j0 + 3.0 * under * under * sink * j1 + 3.0 * under * sink * sink * j2 + sink * sink * sink * j3;
}

fn beamlight(origin: vec3f, ray: vec3f, reach: f32, plate: vec3f) -> f32 {
  let q = origin - plate;
  let b = dot(ray, q);
  let c2 = max(dot(q, q) - b * b, 0.03);
  let sink = -ray.y;
  let under = b * ray.y - q.y;
  var s0 = b;
  var s1 = reach + b;
  if (sink > 1e-4) {
    s0 = max(s0, -under / sink);
  } else if (sink < -1e-4) {
    s1 = min(s1, -under / sink);
  } else if (under <= 0.0) {
    return 0.0;
  }
  if (s1 <= s0) { return 0.0; }
  let nearest = clamp(-b, s0 - b, s1 - b);
  return max(beamUpTo(s1, c2, under, sink) - beamUpTo(s0, c2, under, sink), 0.0) * BEAM_GAIN * exp(-nearest * params.density);
}

// ── THE FIELDS' AIR ──
const MIST_TOP: f32 = -20.0;
const MIST_FADE: f32 = 9.0;
// How thick the mist is at its top, per metre.
const MIST_THICK: f32 = 0.035;
const STRIKE_TONE = vec3f(0.56, 0.74, 1.0);

fn airHash(p: vec2f) -> f32 {
  var q = fract(p * vec2f(0.1031, 0.1030));
  q += dot(q, q.yx + 33.33);
  return fract((q.x + q.y) * q.x);
}

fn airNoise(p: vec2f) -> f32 {
  let cell = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(mix(airHash(cell), airHash(cell + vec2f(1.0, 0.0)), u.x), mix(airHash(cell + vec2f(0.0, 1.0)), airHash(cell + vec2f(1.0, 1.0)), u.x), u.y);
}

fn airBillow(p: vec2f) -> f32 {
  return 0.5 * airNoise(p) + 0.3 * airNoise(p * 2.13 + 7.1) + 0.2 * airNoise(p * 4.37 + 3.7);
}

// What is there where nothing is. Lighter low down all round (the air between here and the limit of sight),
// dark overhead but for a ceiling of cloud, torn, that drifts; and lightning lights the cloud over where it struck.
fn skyAt(ray: vec3f, toStrike: vec2f, live: f32) -> vec3f {
  let band = exp(-abs(ray.y) * 4.0);
  let ceiling = ray.xz / (max(ray.y, 0.0) + 0.22);
  let cloud = airBillow(ceiling * 0.55 + vec2f(frameU.absTime * 0.012, 0.0));
  let torn = smoothstep(0.42, 0.78, cloud) * smoothstep(0.0, 0.25, ray.y);
  let toward = max(dot(normalize(ray.xz + vec2f(1e-5)), toStrike), 0.0);
  return params.color * (0.3 + 0.75 * band + 0.9 * torn) + STRIKE_TONE * (live * (0.03 + 0.2 * cloud) * toward * toward * smoothstep(-0.05, 0.3, ray.y));
}

struct Air {
  clear: f32, // how much of what is drawn comes through
  light: vec3f, // what the air itself sends
};

fn fieldAir(origin: vec3f, ray: vec3f, reach: f32) -> Air {
  let strike = strikeOf(params.strike, params.travel);
  let struck = mix(strike.start, strike.end, 0.5);
  let live = params.flash * strike.live;
  // Where this ray meets the mist's top (or, if it never does, where it ends): the top is in billows there.
  let level = pathAt(origin.z).y + MIST_TOP;
  var meets = min(reach, 300.0);
  if (abs(ray.y) > 1e-4) {
    let t = (level - origin.y) / ray.y;
    if (t > 0.0) { meets = min(t, meets); }
  }
  let there = origin + ray * meets;
  let billow = airBillow(there.xz * 0.02 + vec2f(frameU.absTime * 0.02, frameU.absTime * 0.013));
  let top = level + (billow - 0.5) * 16.0;
  // How much air the ray crosses: the thin air everywhere, and the mist, which is thicker by e every MIST_FADE
  // metres down. Along a straight ray that is the integral of an exponential: closed.
  let thin = reach * params.density;
  let under = exp(clamp(-(origin.y - top) / MIST_FADE, -30.0, 3.0));
  let sinks = ray.y / MIST_FADE;
  var along = reach;
  if (abs(sinks) > 1e-5) { along = (1.0 - exp(clamp(-sinks * reach, -30.0, 30.0))) / sinks; }
  let thick = min(MIST_THICK * params.mist * under * along, 20.0);
  var air: Air;
  air.clear = exp(-(thin + thick));
  // The mist is lit from behind and within: cold, more where it is piled up, a little by the pods, and by
  // lightning, most near where it struck.
  let near = 22.0 / (22.0 + distance(there, struck));
  let mist = params.color * (0.4 + 2.3 * billow * billow) + params.podColor * (0.008 + 0.022 * billow) + STRIKE_TONE * (live * 0.6 * near * near);
  let toStrike = normalize(struck.xz - origin.xz + vec2f(1e-4));
  air.light = mix(skyAt(ray, toStrike, live), mist, thick / max(thin + thick, 1e-5)) * (1.0 - air.clear)
    + STRIKE_TONE * (live * 0.4 * airlight(origin, ray, reach, struck));
  return air;
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let lit = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let view = makeView();
  let ray = rayAt(view, uv);
  let z = viewDepth(uv);
  // Nothing drawn here: the tunnel's own dark, all haze.
  let reach = select(z / max(dot(ray, view.forward), 1e-4), params.far, z < 0.0);
  let clear = exp(-reach * params.density);
  var air = params.eyeColor * params.eyes * airlight(params.eye, ray, reach, params.eyesAt);
  air = air + lampTone(params.station + -2.0) * params.lamp * hallLamp(params.lamp0.z) * beamlight(params.eye, ray, reach, params.lamp0 + vec3f(0.0, LAMP_HANGS, 0.0));
  air = air + lampTone(params.station + -1.0) * params.lamp * hallLamp(params.lamp1.z) * beamlight(params.eye, ray, reach, params.lamp1 + vec3f(0.0, LAMP_HANGS, 0.0));
  air = air + lampTone(params.station + 0.0) * params.lamp * hallLamp(params.lamp2.z) * beamlight(params.eye, ray, reach, params.lamp2 + vec3f(0.0, LAMP_HANGS, 0.0));
  air = air + lampTone(params.station + 1.0) * params.lamp * hallLamp(params.lamp3.z) * beamlight(params.eye, ray, reach, params.lamp3 + vec3f(0.0, LAMP_HANGS, 0.0));
  air = air + lampTone(params.station + 2.0) * params.lamp * hallLamp(params.lamp4.z) * beamlight(params.eye, ray, reach, params.lamp4 + vec3f(0.0, LAMP_HANGS, 0.0));
  if (params.place > 0.5) {
    let field = fieldAir(params.eye, ray, reach);
    return vec4f(lit.rgb * field.clear + field.light + air * params.glow, lit.a);
  }
  return vec4f(mix(params.color, lit.rgb, clear) + air * params.glow, lit.a);
}

struct Params {
  eye: vec3f, // @default 0  Camera position (drive from the camera).
  aim: vec3f, // @default 0  Camera look-at (drive from the camera).
  fov: f32, // @default 50  Camera vertical field of view, degrees.
  far: f32, // @default 400  Camera far plane (depth arrives as distance ÷ far).
  roll: f32, // @default 0  Camera roll, degrees (drive from the camera).
  radius: f32, // @default 1.2  World radius of the occlusion search, metres.
  strength: f32, // @default 0.75  How much of the occlusion darkens the frame.
  power: f32, // @default 1.4  Contrast of the occlusion.
};
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
@group(0) @binding(5) var inputTexture2: texture_2d<f32>;

// T1383b: the camera's right vector with its ROLL — world up turned about the view axis by
// roll degrees (Rodrigues, right-handed about the camera's +z: the angle is negated about forward),
// exactly as camera.ts guardedRolledUp builds the render's view (T1433b).
fn rolledRight(forward: vec3f, rollDeg: f32) -> vec3f {
  var up = select(vec3f(0.0, 1.0, 0.0), vec3f(0.0, 0.0, 1.0), abs(forward.y) > 0.999);
  let t = radians(-rollDeg);
  up = up * cos(t) + cross(forward, up) * sin(t) + forward * dot(forward, up) * (1.0 - cos(t));
  return normalize(cross(forward, up));
}

struct View {
  forward: vec3f,
  right: vec3f,
  up: vec3f,
  tanHalf: f32,
  aspect: f32,
};

fn makeView() -> View {
  var v: View;
  v.forward = normalize(params.aim - params.eye);
  v.right = rolledRight(v.forward, params.roll);
  v.up = cross(v.right, v.forward);
  v.tanHalf = tan(radians(params.fov) * 0.5);
  v.aspect = frameU.resolution.x / max(frameU.resolution.y, 1.0);
  return v;
}

fn rayAt(v: View, uv: vec2f) -> vec3f {
  let ndc = vec2f(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0);
  return normalize(v.forward + v.right * ndc.x * v.tanHalf * v.aspect + v.up * ndc.y * v.tanHalf);
}

fn depthTexel(uv: vec2f) -> vec2i {
  let size = vec2f(textureDimensions(inputTexture1));
  return clamp(vec2i(uv * size), vec2i(0), vec2i(size) - vec2i(1));
}

// View-plane distance at uv, or a negative number where there is no surface.
fn viewDepth(uv: vec2f) -> f32 {
  let d = textureLoad(inputTexture1, depthTexel(uv), 0).r;
  return select(d * params.far, -1.0, d >= 0.9999 || d <= 0.0);
}

fn worldAt(v: View, uv: vec2f, z: f32) -> vec3f {
  let ray = rayAt(v, uv);
  return params.eye + ray * (z / max(dot(ray, v.forward), 1e-4));
}

// World point → (uv, view-plane distance); z ≤ 0 means behind the camera.
fn project(v: View, world: vec3f) -> vec3f {
  let rel = world - params.eye;
  let z = dot(rel, v.forward);
  let x = dot(rel, v.right) / (max(z, 1e-4) * v.tanHalf * v.aspect);
  let y = dot(rel, v.up) / (max(z, 1e-4) * v.tanHalf);
  return vec3f(x * 0.5 + 0.5, 0.5 - y * 0.5, z);
}

fn ignHash(pixel: vec2f) -> f32 {
  return fract(52.9829189 * fract(dot(pixel, vec2f(0.06711056, 0.00583715))));
}

const DIRECTIONS: u32 = 8u;
const STEPS: u32 = 6u;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let color = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let v = makeView();
  let z = viewDepth(uv);
  let encoded = textureLoad(inputTexture2, depthTexel(uv), 0);
  if (z < 0.0 || encoded.a <= 0.0) { return color; }
  let n = normalize(encoded.rgb * 2.0 - 1.0);
  let p = worldAt(v, uv, z);
  let helper = select(vec3f(0.0, 1.0, 0.0), vec3f(1.0, 0.0, 0.0), abs(n.y) > 0.9);
  let t = normalize(cross(n, helper));
  let b = cross(n, t);
  let spin = ignHash(uv * frameU.resolution) * 6.2831853;
  var occlusion = 0.0;
  for (var i = 0u; i < DIRECTIONS; i = i + 1u) {
    let angle = spin + f32(i) * 6.2831853 / f32(DIRECTIONS);
    let dir = t * cos(angle) + b * sin(angle);
    var best = 0.0;
    for (var s = 1u; s <= STEPS; s = s + 1u) {
      let distance = params.radius * (f32(s) / f32(STEPS)) * (f32(s) / f32(STEPS));
      let probe = project(v, p + dir * distance);
      if (probe.z <= 0.0 || any(probe.xy < vec2f(0.0)) || any(probe.xy > vec2f(1.0))) { break; }
      let sz = viewDepth(probe.xy);
      if (sz < 0.0) { continue; }
      let sp = worldAt(v, probe.xy, sz);
      let toSample = sp - p;
      let length2 = dot(toSample, toSample);
      let elevation = dot(n, toSample) * inverseSqrt(max(length2, 1e-6));
      let falloff = 1.0 - smoothstep(params.radius * params.radius * 0.5, params.radius * params.radius * 2.0, length2);
      best = max(best, (elevation - 0.08) * falloff);
    }
    occlusion = occlusion + clamp(best, 0.0, 1.0);
  }
  let ao = pow(clamp(1.0 - occlusion / f32(DIRECTIONS), 0.0, 1.0), params.power);
  return vec4f(color.rgb * mix(1.0, ao, params.strength), color.a);
}

struct Params {
  eye: vec3f, // @default 0  Camera position (drive from the camera).
  aim: vec3f, // @default 0  Camera look-at (drive from the camera).
  fov: f32, // @default 50  Camera vertical field of view, degrees.
  far: f32, // @default 400  Camera far plane (depth arrives as distance ÷ far).
  roll: f32, // @default 0  Camera roll, degrees (drive from the camera).
  strength: f32, // @default 1  Overall reflection strength.
  maxDistance: f32, // @default 40  Longest reflection ray, metres.
  thickness: f32, // @default 0.6  How thick a surface is assumed behind the depth buffer, metres.
  roughnessCutoff: f32, // @default 0.45  Surfaces rougher than this reflect nothing.
};
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
@group(0) @binding(5) var inputTexture2: texture_2d<f32>;

// T1383b: the camera's right vector with its ROLL — world up turned about the view axis by
// roll degrees (Rodrigues, right-handed about the camera's +z: the angle is negated about forward),
// exactly as camera.ts guardedRolledUp builds the render's view (T1433b).
fn rolledRight(forward: vec3f, rollDeg: f32) -> vec3f {
  var up = select(vec3f(0.0, 1.0, 0.0), vec3f(0.0, 0.0, 1.0), abs(forward.y) > 0.999);
  let t = radians(-rollDeg);
  up = up * cos(t) + cross(forward, up) * sin(t) + forward * dot(forward, up) * (1.0 - cos(t));
  return normalize(cross(forward, up));
}

struct View {
  forward: vec3f,
  right: vec3f,
  up: vec3f,
  tanHalf: f32,
  aspect: f32,
};

fn makeView() -> View {
  var v: View;
  v.forward = normalize(params.aim - params.eye);
  v.right = rolledRight(v.forward, params.roll);
  v.up = cross(v.right, v.forward);
  v.tanHalf = tan(radians(params.fov) * 0.5);
  v.aspect = frameU.resolution.x / max(frameU.resolution.y, 1.0);
  return v;
}

fn rayAt(v: View, uv: vec2f) -> vec3f {
  let ndc = vec2f(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0);
  return normalize(v.forward + v.right * ndc.x * v.tanHalf * v.aspect + v.up * ndc.y * v.tanHalf);
}

fn depthTexel(uv: vec2f) -> vec2i {
  let size = vec2f(textureDimensions(inputTexture1));
  return clamp(vec2i(uv * size), vec2i(0), vec2i(size) - vec2i(1));
}

// View-plane distance at uv, or a negative number where there is no surface.
fn viewDepth(uv: vec2f) -> f32 {
  let d = textureLoad(inputTexture1, depthTexel(uv), 0).r;
  return select(d * params.far, -1.0, d >= 0.9999 || d <= 0.0);
}

fn worldAt(v: View, uv: vec2f, z: f32) -> vec3f {
  let ray = rayAt(v, uv);
  return params.eye + ray * (z / max(dot(ray, v.forward), 1e-4));
}

// World point → (uv, view-plane distance); z ≤ 0 means behind the camera.
fn project(v: View, world: vec3f) -> vec3f {
  let rel = world - params.eye;
  let z = dot(rel, v.forward);
  let x = dot(rel, v.right) / (max(z, 1e-4) * v.tanHalf * v.aspect);
  let y = dot(rel, v.up) / (max(z, 1e-4) * v.tanHalf);
  return vec3f(x * 0.5 + 0.5, 0.5 - y * 0.5, z);
}

fn ignHash(pixel: vec2f) -> f32 {
  return fract(52.9829189 * fract(dot(pixel, vec2f(0.06711056, 0.00583715))));
}

const STEPS: u32 = 40u;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let color = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let encoded = textureLoad(inputTexture2, depthTexel(uv), 0);
  let roughness = encoded.a;
  let v = makeView();
  let z = viewDepth(uv);
  if (z < 0.0 || roughness <= 0.0 || roughness > params.roughnessCutoff) { return color; }
  let n = normalize(encoded.rgb * 2.0 - 1.0);
  let p = worldAt(v, uv, z);
  let view = normalize(p - params.eye);
  let r = reflect(view, n);
  let fresnel = 0.04 + 0.96 * pow(1.0 - clamp(dot(-view, n), 0.0, 1.0), 5.0);
  let gloss = 1.0 - smoothstep(0.05, params.roughnessCutoff, roughness);
  if (fresnel * gloss < 0.01) { return color; }
  let jitter = ignHash(uv * frameU.resolution + vec2f(frameU.absFrame * 3.1));
  var previous = 0.0;
  var hit = vec3f(-1.0);
  for (var i = 1u; i <= STEPS; i = i + 1u) {
    let travel = params.maxDistance * pow((f32(i) - 1.0 + jitter) / f32(STEPS), 2.0) + 0.05;
    let probe = project(v, p + r * travel);
    if (probe.z <= 0.0 || any(probe.xy < vec2f(0.0)) || any(probe.xy > vec2f(1.0))) { break; }
    let sceneZ = viewDepth(probe.xy);
    if (sceneZ > 0.0 && probe.z > sceneZ && probe.z - sceneZ < params.thickness + travel * 0.02) {
      // Refine between the last miss and this hit.
      var lo = previous;
      var hi = travel;
      for (var k = 0; k < 5; k = k + 1) {
        let mid = (lo + hi) * 0.5;
        let q = project(v, p + r * mid);
        let qz = viewDepth(q.xy);
        if (qz > 0.0 && q.z > qz) { hi = mid; } else { lo = mid; }
      }
      hit = project(v, p + r * hi);
      break;
    }
    previous = travel;
  }
  if (hit.z <= 0.0) { return color; }
  let edge = smoothstep(0.0, 0.08, min(min(hit.x, 1.0 - hit.x), min(hit.y, 1.0 - hit.y)));
  let reflected = textureSampleLevel(inputTexture, inputSampler, hit.xy, 0.0).rgb;
  let amount = clamp(fresnel * gloss * edge * params.strength, 0.0, 1.0);
  return vec4f(mix(color.rgb, color.rgb + reflected, amount), color.a);
}
